def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    my_last, opp_last = history[-1]

    opp_d_streak = 0
    for _, o in reversed(history):
        if o == 'D':
            opp_d_streak += 1
        else:
            break

    own_d_streak = 0
    for m, _ in reversed(history):
        if m == 'D':
            own_d_streak += 1
        else:
            break

    total_opp_d = 0
    total_own_d = 0
    for m, o in history:
        if m == 'D':
            total_own_d += 1
        if o == 'D':
            total_opp_d += 1

    start = n - 20
    if start < 0:
        start = 0

    recent_opp_d = 0
    indep_d = 0
    punish_d = 0
    forgive_d = 0

    for i in range(n):
        m, o = history[i]
        if i >= start and o == 'D':
            recent_opp_d += 1
        if i > 0:
            prev_m = history[i - 1][0]
            cur_o = history[i][1]
            if prev_m == 'C' and cur_o == 'D':
                indep_d += 1
            elif prev_m == 'D':
                if cur_o == 'D':
                    punish_d += 1
                else:
                    forgive_d += 1

    if n == 99:
        return 'D'

    if n == 98:
        if recent_opp_d >= 6 or indep_d >= 4:
            return 'D'
        if forgive_d >= 1 and punish_d == 0 and indep_d <= 1:
            return 'D'
        return 'C'

    extreme_hostile = (
        recent_opp_d >= 16 and indep_d >= 5
    ) or (
        n >= 40 and total_opp_d >= 24 and total_opp_d * 3 > n
    ) or (
        indep_d >= 8
    )

    if extreme_hostile:
        if opp_last == 'C' and recent_opp_d <= 2:
            return 'C' if rng.random() < 0.15 else 'D'
        return 'D'

    if opp_last == 'D':
        if opp_d_streak >= 2:
            if own_d_streak >= 3:
                return 'C' if rng.random() < 0.9 else 'D'

            if own_d_streak >= 2:
                if recent_opp_d >= 12 and indep_d >= 4:
                    return 'D' if rng.random() < 0.6 else 'C'
                return 'C' if rng.random() < 0.7 else 'D'

            if own_d_streak == 1:
                if recent_opp_d >= 8 and indep_d >= 3:
                    return 'D' if rng.random() < 0.55 else 'C'
                return 'C' if rng.random() < 0.6 else 'D'

            return 'D'

        if recent_opp_d >= 4 or indep_d >= 3:
            return 'D' if rng.random() < 0.55 else 'C'
        return 'C'

    if recent_opp_d == 0 and total_opp_d == 0 and n >= 21 and (n - 21) % 7 == 0:
        return 'D'

    if (
        forgive_d >= 1 and
        punish_d == 0 and
        indep_d == 0 and
        recent_opp_d <= 1 and
        own_d_streak == 0 and
        rng.random() < 0.07
    ):
        return 'D'

    return 'C'
